```

### Custom background

By default, a sheet uses the system's translucent material background (Liquid Glass on iOS 26). Use the [`presentationBackground`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#presentationbackgroundstyle) modifier on `Group` to paint the sheet yourself, which also opts the sheet out of that translucent material. It accepts any `ShapeStyle`: a solid color, a material, or a gradient.

> iOS 26 renders a material, such as `{ type: 'material', material: 'ultraThin' }`, as a flat color rather than a translucent blur. Pick a background that also reads well opaque.

> Prefer `presentationBackground` over a `background` modifier on the sheet's content. A `background` sits _behind_ the content's own background, so a `Form` or `List` covers it, and the color shows inconsistently as the sheet moves between detents. `presentationBackground` colors the sheet surface itself, so it stays consistent at every detent. When the content is a `Form` or `List`, also add [`scrollContentBackground('hidden')`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#scrollcontentbackgroundvisible) so the sheet color shows through the grouped background.

```tsx BottomSheetBackgroundColorExample.tsx
import { useState } from 'react';
import {
  Host,
  BottomSheet,
  Button,
  Group,
  Text,
  VStack,
} from '@expo/ui/swift-ui';
import {
  presentationBackground,
  presentationDetents,
  padding,
  foregroundStyle,
} from '@expo/ui/swift-ui/modifiers';

export default function BottomSheetBackgroundColorExample() {
  const [isPresented, setIsPresented] = useState(false);

  return (
    <Host style={{ flex: 1 }}>
      <VStack>
        <BottomSheet
          isPresented={isPresented}
          onIsPresentedChange={setIsPresented}
          anchor={
            <Button
              label="Open sheet"
              onPress={() => setIsPresented(true)}
            />
          }>
          <Group
            modifiers={[
              presentationDetents(['medium', 'large']),
              presentationBackground('#ffffff'),
            ]}>
            <VStack modifiers={[padding({ all: 20 })]}>
              <Text modifiers={[foregroundStyle('#000000')]}>
                Solid white sheet background.
              </Text>
              <Button
                label="Close"
                onPress={() => setIsPresented(false)}
              />
            </VStack>
          </Group>
        </BottomSheet>
      </VStack>
    </Host>
  );
}
```

### Color scheme

A sheet follows the device's light or dark appearance by default. To use your app's appearance instead, add the [`preferredColorScheme`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#preferredcolorschemecolorscheme) modifier to the `Group`. The `Host` `colorScheme` prop changes the sheet's content but not its background.

```tsx BottomSheetColorSchemeExample.tsx
import { useState } from 'react';
import {
  Host,
  BottomSheet,
  Button,
  Group,
  Text,
  VStack,
} from '@expo/ui/swift-ui';
import {
  padding,
  preferredColorScheme,
  presentationDetents,
} from '@expo/ui/swift-ui/modifiers';

export default function BottomSheetColorSchemeExample() {
  const [isPresented, setIsPresented] = useState(false);
  const appearance = 'dark';

  return (
    <Host style={{ flex: 1 }} colorScheme={appearance}>
      <VStack>
        <BottomSheet
          isPresented={isPresented}
          onIsPresentedChange={setIsPresented}
          anchor={
            <Button
              label="Open sheet"
              onPress={() => setIsPresented(true)}
            />
          }>
          <Group
            modifiers={[
              presentationDetents(['medium']),
              preferredColorScheme(appearance),
            ]}>
            <VStack modifiers={[padding({ all: 20 })]}>
              <Text>This sheet is always dark.</Text>
            </VStack>
          </Group>
        </BottomSheet>
      </VStack>
    </Host>
  );
}
```

### Bottom sheet with presentation detents

Use the [`presentationDetents`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#presentationdetentsdetents-options) modifier on `Group` to control the available heights. You can use:

-   `'medium'`: System medium height (approximately half screen)
-   `'large'`: System large height (full screen)
-   `{ fraction: number }`: Fraction of screen height (0-1)
-   `{ height: number }`: Fixed height in points

```tsx BottomSheetWithDetentsExample.tsx
import { useState } from 'react';
import {
  Host,
  BottomSheet,
  Button,
  Group,
  Text,
  VStack,
} from '@expo/ui/swift-ui';
import { presentationDetents } from '@expo/ui/swift-ui/modifiers';

export default function BottomSheetWithDetentsExample() {
  const [isPresented, setIsPresented] = useState(false);

  return (
    <Host style={{ flex: 1 }}>
      <VStack>
        <BottomSheet
          isPresented={isPresented}
          onIsPresentedChange={setIsPresented}
          anchor={
            <Button
              label="Open sheet"
              onPress={() => setIsPresented(true)}
            />
          }>
          <Group
            modifiers={[
              presentationDetents([
                'medium',
                'large',
                { fraction: 0.3 },
                { height: 200 },
              ]),
            ]}>
            <Text>This sheet can snap to multiple heights.</Text>
          </Group>
        </BottomSheet>
      </VStack>
