### Selection and edit mode

Enable selection, deletion, and reordering of list items using the [`List.ForEach`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/list.md#listforeach) compound component with `onDelete` and `onMove` props.

-   Use the [`environment`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#environmentkey-value) modifier to enable edit mode
-   Use the `keyExtractor` prop to identify items
-   Use the [`selection`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/list.md#selection) prop to control selected items
-   Use [`moveDisabled`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#movedisableddisabled) and [`deleteDisabled`](https://docs.expo.dev/versions/v58.0.0/sdk/ui/swift-ui/modifiers.md#deletedisableddisabled) modifiers to disable these actions on individual items

```tsx EditableListExample.tsx
import { useState } from 'react';
import {
  Host,
  List,
  Label,
  Section,
  Button,
  Toggle,
} from '@expo/ui/swift-ui';
import { environment } from '@expo/ui/swift-ui/modifiers';

type Task = { id: string; title: string };

const INITIAL_TASKS: Task[] = [
  { id: '1', title: 'Task 1' },
  { id: '2', title: 'Task 2' },
  { id: '3', title: 'Task 3' },
  { id: '4', title: 'Task 4' },
];

function renderTask({ item }: { item: Task }) {
  return <Label title={item.title} />;
}

export default function EditableListExample() {
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [editMode, setEditMode] = useState(false);

  const handleDelete = (indices: number[]) => {
    setTasks(prev => prev.filter((_, i) => !indices.includes(i)));
  };

  const handleMove = (
    sourceIndices: number[],
    destination: number
  ) => {
    setTasks(prev => {
      const newTasks = [...prev];
      const [removed] = newTasks.splice(sourceIndices[0], 1);
      const adjustedDest =
        sourceIndices[0] < destination
          ? destination - 1
          : destination;
      newTasks.splice(adjustedDest, 0, removed);
      return newTasks;
    });
  };

  return (
    <Host style={{ flex: 1 }}>
      <List
        selection={selectedIds}
        onSelectionChange={ids => setSelectedIds(ids.map(String))}
        modifiers={[
          environment('editMode', editMode ? 'active' : 'inactive'),
        ]}>
        <Section title="Settings">
          <Toggle
            label="Edit mode"
            isOn={editMode}
            onIsOnChange={setEditMode}
          />
        </Section>
        <Section title="Tasks">
          <List.ForEach
            data={tasks}
            keyExtractor={task => task.id}
            onDelete={handleDelete}
            onMove={handleMove}>
            {renderTask}
          </List.ForEach>
        </Section>
      </List>
    </Host>
  );
}
```

### Pull to refresh

